111:   claimToolCall(body: unknown, serverName: string): ClaimResult {
112:     if (Array.isArray(body)) return { call: { id: null }, error: 'Batch tools/call is not supported by the managed host' }
113:     if (!isRecord(body) || body.method !== 'tools/call' || !isRecord(body.params)) return {}
114:     const call = { id: body.id ?? null }
115:     const name = body.params.name
116:     const args = body.params.arguments
117:     const meta = isRecord(body.params._meta) ? body.params._meta[UAR_TOOL_ADMISSION_META_KEY] : undefined
118:     if (typeof name !== 'string' || !isRecord(args) || !isRecord(meta)) {
119:       return { call, error: 'Managed tool call is missing exact admission identity' }
120:     }
121:     const admissionId = meta.admissionId
122:     const invocationId = meta.invocationId
123:     const record = typeof admissionId === 'string' ? this.records.get(admissionId) : undefined
124:     if (!record || typeof invocationId !== 'string') return { call, error: 'Managed tool admission is unknown' }
125:     const invocation = record.invocation
126:     const providerName = encodeUarProviderToolName(`${serverName}__${name}`)
127:     const matches =
128:       meta.version === UAR_TOOL_ADMISSION_VERSION &&
129:       meta.runtimeEpoch === invocation.runtimeEpoch &&
130:       meta.hostEpoch === this.hostEpoch &&
131:       meta.authorityRevision === invocation.authorityRevision &&
132:       invocationId === invocation.invocationId &&
133:       invocation.mountedServerId === serverName &&
134:       invocation.nativeToolName === name &&
135:       invocation.providerToolName === providerName &&
136:       record.argumentDigest === argumentDigest(args)
137:     if (!matches) {
138:       this.transition(record, 'invalidated')
139:       return { call, error: 'Managed tool call does not match its prepared admission' }
140:     }
141:     const currentDisposition = this.options.disposition(providerName)
142:     if (currentDisposition === 'deny' || (currentDisposition === 'ask' && record.decision !== true)) {
143:       this.transition(record, 'invalidated')
144:       return { call, error: 'Managed tool policy changed before dispatch' }
145:     }
146:     if (record.state !== 'authorized') return { call, error: 'Managed tool admission is not executable' }
147:     if (!hasLiveHostClaimFacts(invocation)) return { call, error: 'Managed tool lease or budget is not executable' }
148:     try {
149:       this.transition(record, 'claimed')
150:     } catch {
151:       return { call, error: 'Managed tool claim evidence could not be persisted; dispatch was blocked' }
152:     }

